PersonalHomeData = class("PersonalHomeData")
function PersonalHomeData:initialize()
    self.rid = -1
    self.exhibitRootID = -1
    self.exhibitDic = {}
    self.cacheMapInfo=""
    self.carIndex=-1
    self.carInfos=nil
    self.carBuilderDic={}
    self.buildParamDic ={}
end

function PersonalHomeData:SetRID(rid) self.rid = rid end

function PersonalHomeData:GetRID()  return self.rid end

function PersonalHomeData:SetExhibitRootID(id) self.exhibitRootID = id end

function PersonalHomeData:GetExhibitRootID() return self.exhibitRootID end

function PersonalHomeData:GetRootExhibit() return self.exhibitDic[self.exhibitRootID]  end

function PersonalHomeData:SetCacheMapInfo(mapInfo)
    if mapInfo == nil then
        mapInfo = ""
    end
    self.cacheMapInfo = mapInfo
end

function PersonalHomeData:GetCacheMapInfo() return self.cacheMapInfo end

function PersonalHomeData:AddCarBuilderId(carIndex,carBuilderId)
    self.carBuilderDic[carIndex]=carBuilderId
end

function PersonalHomeData:AddCarBuilderParam(param)
    table.insert(self.buildParamDic,param)
end


function PersonalHomeData:GetCarInfos() return self.carInfos end

function PersonalHomeData:GetExhibitByID(id)
    for serverID, exhibit in pairs(self.exhibitDic) do
        if exhibit:GetExhibitID()==id then
            return exhibit
        end
    end
    return nil
end

---@return ExhibitData
function PersonalHomeData:GetUnPutTrophyExhibit()---由于2d问题 零时返回 nil
    for serverID, exhibit in pairs(self.exhibitDic) do
        if exhibit:GetType()==ExhibitType.Trophy and exhibit:GetParentServerID()<1 then
            return nil
            --return exhibit
        end
    end
end

function PersonalHomeData:GetCanSetSite(type)
    for serverID, exhibit in pairs(self.exhibitDic) do
        for slotID, childServerID in pairs(exhibit:GetChildDic()) do
            if exhibit:GetSlotTypeDic()[slotID]==type and childServerID<0 then
                return serverID,slotID
            end
        end
    end
    return nil
end

---@param exhibit ExhibitData
function PersonalHomeData:AddExhibit(exhibit)
    self.exhibitDic[exhibit:GetServerID()] = exhibit
end

---@return  table<number, ExhibitData> @展品数据组
function PersonalHomeData:GetExhibitDic() return self.exhibitDic end

---@return  table<number, ExhibitData>,table<number, ExhibitData> @获取背包里显示的家具  @已装备的家具   目前家具只有
function PersonalHomeData:GetBagExhibitList(type)
    local list = {}
    local equippedList={}
    for i, exhibitData in pairs(self.exhibitDic) do
        if exhibitData:GetParentServerID()<1 then
            if exhibitData:GetServerID() ~= self.exhibitRootID  and exhibitData:GetType()~=ExhibitType.Car and exhibitData:GetType()~=ExhibitType.PreviewCar then
                if type==nil or type == exhibitData:GetType() then
                    table.insert(list,exhibitData)
                end
            end
        else
            if exhibitData:GetServerID() ~= self.exhibitRootID  and exhibitData:GetType()~=ExhibitType.Car and exhibitData:GetType()~=ExhibitType.PreviewCar then
                if type==nil or type == exhibitData:GetType() then
                    table.insert(equippedList,exhibitData)
                end
            end
        end
    end
    return list,equippedList
end

---@return  ExhibitData @展品
function PersonalHomeData:GetExhibitByServerID(serverId) return self.exhibitDic[serverId] end

---@param exhibitData ExhibitData
function PersonalHomeData:UpdateMapNode(exhibitData)
    if self.MapNodeDic[exhibitData:GetServerID()]==nil then
        self.MapNodeDic[exhibitData:GetServerID()]  = PersonalHomeMapNode()
    end
    local mapNode= self.MapNodeDic[exhibitData:GetServerID()]
    local data={
        ServerID = exhibitData:GetServerID(),
        ID = exhibitData:GetExhibitID(),
        ChildDic = exhibitData:GetChildDic()
    }
    mapNode:SetDataMsg(data)
end

function PersonalHomeData:GetJson_MapNodeDic()
    local exhibitData = self:GetRootExhibit()
    local mapNodeDic={}
    self:SetMapNode(exhibitData,mapNodeDic)
    local jsonData = Dll_JSON.encode(mapNodeDic)
    return jsonData
end

---@param exhibitData ExhibitData
---@param mapNodeDic table<number,PersonalHomeMapNode>
function PersonalHomeData:SetMapNode(exhibitData,mapNodeDic)
    ---@type  table<number,number> @展示品子节点<slot,ID>
    local dic = exhibitData:GetChildDic()
    table.insert(mapNodeDic,exhibitData:GetPersonalHomeMapNode())
    for slot, serverID in pairs(dic) do
        if serverID>0 then
            local childExhibitData = self:GetExhibitByServerID(serverID)
            self:SetMapNode(childExhibitData,mapNodeDic)
        end
    end
end


