---@param furnitureList table<number,SC_Furniture>
function PersonalHomeDataManager:UpdatePersonalHomeData(furnitureList,islogin)--留给服务器消息初始化
    if  self.selfInfo:GetRID()>0 and PlayerDataManager:Get():GetPlayerRID()~=self.selfInfo:GetRID() then
        self.selfInfo = PersonalHomeData()
        self.selfInfo:SetRID(PlayerDataManager:Get():GetPlayerRID())
    end
   -- local IsOpenPersonalHome = self.curInfo~=nil
    if furnitureList then
        for i = 1, #furnitureList do
            -----@type dictarticle_config_cell
            local cfgArticleData = CommonHelper:GetTableDataByID(ConfigNames.article_config,furnitureList[i].furnitureId)
            if cfgArticleData then
                -----@type dictexhibit_config_cell
                local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config,cfgArticleData.propsadd)
                if cfgdata then
                    local exhibitData = self.selfInfo:GetExhibitByServerID(furnitureList[i].furnitureInx)
                    if exhibitData==nil then
                        exhibitData = ExhibitData(furnitureList[i].furnitureInx,cfgArticleData.propsadd,furnitureList[i].furnitureId)
                    end
                    if islogin then
                        self.selfInfo:AddExhibit(exhibitData)
                        if self.selfInfo:GetExhibitRootID() <0  and exhibitData:GetType() == ExhibitType.Home then
                            self.selfInfo:SetExhibitRootID(exhibitData:GetServerID())
                        end
                    else
                        if self.selfInfo:GetExhibitByServerID(furnitureList[i].furnitureInx) == nil then
                            self.selfInfo:AddExhibit(exhibitData)
                        end
                    end
                else
                    print(cfgArticleData.propsadd,"MEIYOU")
                end
            end
        end
    end
    if islogin then
        for i = 100, 105 do
            ---@type dictexhibit_config_cell
            local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config,i )
            if cfgdata then
                local exhibitData = ExhibitData(cfgdata.C_ID,cfgdata.C_ID)
                self.selfInfo:AddExhibit(exhibitData)
            end
        end
    end
end

