function PersonalHomeDataManager:TryUpdateExhibitNode(childExhibit,nodeServerId,nodeSlot)
    local IsInstall=true
    ---@type ExhibitBoxInfo
    local boxInfo = ExhibitBoxMgr:Get():GetBoxInfoByServerIdSlot(nodeServerId,nodeSlot)
    local childExhibitBuilder = ExhibitBuilderManager:Get():GetBuilderById(childExhibit:GetExhibitBuilderId())
    if nodeServerId == nil or nodeServerId == -1 then
        boxInfo= ExhibitBoxMgr:Get():GetBoxInfoByServerIdSlot(childExhibit:GetParentInfo())
        IsInstall=false
    end
    if self:IsCanUpdateExhibitNode(childExhibit,nodeServerId,nodeSlot) then
        if boxInfo~=nil then
            if IsInstall then
                boxInfo:SetDepositServerID(childExhibit:GetServerID())
                UIUtil.SetParentTransform(boxInfo.IBox:GetBoxGameObject(),childExhibitBuilder:GetRoot() ,true)
                CommonHelper:CSGameObjectSetActive(childExhibitBuilder:GetRoot() ,true)
            else
                boxInfo:SetDepositServerID(-1)
                UIUtil.SetParentTransform(ExhibitCacheMgr:Get():GetRoot(),childExhibitBuilder:GetRoot() ,true)
                CommonHelper:CSGameObjectSetActive(childExhibitBuilder:GetRoot() ,false)
            end
        end
        return true
    end
    return false
end

---@param childExhibit ExhibitData
---@param nodeServerId number
---@param nodeSlot number
---@return boolean 是否可以进行替换
function PersonalHomeDataManager:IsCanUpdateExhibitNode(childExhibit, nodeServerId, nodeSlot,isSave)
    if self.curInfo==nil then
        return
    end
    if childExhibit==nil  then
        logError(" childExhibit is null :")
        return false
    end
    isSave = isSave == nil and  true or isSave
    ---情况1 父节点没有展品   exhibit不为空   删除字父节行为

    ---情况2 父节点没有展品   exhibit不为空  且 没有父节点 添加行为

    ---情况3 父节点有展品    exhibit不为空  且 原exhibit没有父节点 交换行为

    ---情况4 父节点有展品    exhibit不为空  且 原exhibit有父节点 交换行为
    ---@type  ExhibitData
    local exhibit,originalChildExhibit,childParentExhibit
    if nodeServerId == nil or nodeServerId == -1 then
        nodeServerId,nodeSlot = childExhibit:GetParentInfo()
        exhibit = self.curInfo:GetExhibitByServerID(nodeServerId)
        if exhibit == nil  then
            logError(" exhibit is null :",nodeServerId)
            return false
        end
        exhibit:SetChild(nodeSlot,-1)
        childExhibit:SetParentInfo(-1,-1)
    else
        exhibit = self.curInfo:GetExhibitByServerID(nodeServerId)
        if exhibit==nil  then
            logError(" exhibit is null :",nodeServerId)
            return false
        end
        if exhibit:CheckCanPutIn(nodeSlot,childExhibit:GetType()) == false then
            return false
        end
        originalChildExhibit = self:GetExhibitByServerID(exhibit:GetChildServerIdBySlot(nodeSlot))
        childParentExhibit  = self:GetExhibitByServerID(childExhibit:GetParentServerID())
        if originalChildExhibit and childParentExhibit then
            childParentExhibit:SetChild(childExhibit:GetParentSlot(),originalChildExhibit:GetServerID())
            originalChildExhibit:SetParentInfo(childExhibit:GetParentInfo())
        else
            if childParentExhibit ~= nil then
                childParentExhibit:SetChild(childExhibit:GetParentSlot(),-1)
            end
            if originalChildExhibit~= nil then
                originalChildExhibit:SetParentInfo(-1,-1)
            end
        end
        exhibit:SetChild(nodeSlot,childExhibit:GetServerID())
        childExhibit:SetParentInfo(nodeServerId,nodeSlot)
    end
    self.curInfo:SetCacheMapInfo(self.curInfo:GetJson_MapNodeDic())
    if isSave then
        PersonalHomeSubsystem:Get():SendSaveInfo()
    end
    return true
end



---检测数据是否合法
function PersonalHomeDataManager:CheckJsonIsRightful(json,isSelf)
    if CommonHelper:IsNullOrEmpty(json) then
        return false
    end
    local mapNodeDic = Dll_JSON.decode(json)
    if mapNodeDic==nil then
        return false
    end
    local IsContain=function(list,v)
        if list~=nil then
            for i = 1, #list do
                if tonumber(list[i])==tonumber(v) then
                    return true
                end
            end
        end
        return false
    end
    for i = 1,#mapNodeDic do
        ---@type PersonalHomeMapNode
        local personalHomeMapNode = mapNodeDic[i]
        if isSelf then
            if self.selfInfo:GetExhibitByServerID(personalHomeMapNode.ServerID) == nil then
                return false
            end
        end
        ---@type dictexhibit_config_cell
        local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config, personalHomeMapNode.ID)
        if cfgdata==nil then
            return false
        else
            local slotGroups = stringSplit(cfgdata.childgroovegroup,':')
            for j = 1, #personalHomeMapNode.ChildDic do
                ---@type SlotInfo
                local slotInfo =  personalHomeMapNode.ChildDic[j]
                if slotInfo.ChildServerID>0 then
                    if IsContain(slotGroups,slotInfo.SlotID)  then
                        ---@type dictpersonalhomeslot_config_cell
                        local cfgslotdata = CommonHelper:GetTableDataByID(ConfigNames.dictpersonalhomeslot_config,slotInfo.SlotID)
                        if cfgslotdata==nil then
                            return false
                        end
                        ---@type dictexhibit_config_cell
                        local childcfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config, slotInfo.ExhibitID)
                        if childcfgdata==nil then
                            return false
                        end
                        if cfgslotdata.type~=childcfgdata.type then
                            return false
                        end
                    else
                        return false
                    end
                end
            end
        end
    end
    if #mapNodeDic<2 then
        return false
    end
    return true
end

function PersonalHomeDataManager:InitHomeExhibit(rid,saveInfo,cars)
    local infos=stringSplit(saveInfo,"_")
    local jsonData=infos[2]
    local carCount
    if infos[3] then
        local versions= stringSplit( infos[3],".")
        if  tonumber(versions[1])<3 then
            jsonData = ""
        end
    end
    if not self:CheckJsonIsRightful(jsonData,PlayerDataManager:Get():GetPlayerRID() == rid)  then
        jsonData = ""
    end
    --if self.curInfo==nil or PlayerDataManager:Get():GetPlayerRID() ~= rid then
        if PlayerDataManager:Get():GetPlayerRID() == rid then
            self.curInfo = self.selfInfo
            carCount = #(CarDataManager:Get():GetCarList())
        else
            self.curInfo = self.otherInfo
            carCount = #cars
            self:InitCarByData(cars)
        end
        self.curInfo:SetRID(rid)
        self.curInfo:SetCacheMapInfo(jsonData)
    --end
    self.curInfo.carIndex = tonumber(infos[1])
    if self.curInfo.carIndex==nil then
        self.curInfo.carIndex=1
    end
    if CommonHelper:IsNullOrEmpty(jsonData) then
        local rootExhibit= self.curInfo:GetRootExhibit()
        if rootExhibit == nil then
            for i = 1, 120 do ---默认120之前都是送的  ---临时处理
            ---@type dictexhibit_config_cell
            local cfgdata = CommonHelper:GetTableDataByID(ConfigNames.dictexhibit_config, i)
                if cfgdata then
                    local exhibitData = ExhibitData(cfgdata.C_ID,cfgdata.C_ID)
                    self.curInfo:AddExhibit(exhibitData)
                    if self.curInfo:GetExhibitRootID() <0  and exhibitData:GetType()==ExhibitType.Home then
                        self.curInfo:SetExhibitRootID(exhibitData:GetServerID())
                        rootExhibit=exhibitData
                    end
                end
            end
        end
        self:SetDefaultSiteInfo(rootExhibit)
        if  PlayerDataManager:Get():GetPlayerRID() == rid then
            self:TrophySetup()
        end
    else
        self:SetExhibitDataSiteInfo(jsonData)
    end
    self:BuildHomeExhibit(carCount)
    --if rid ~= PlayerDataManager:Get():GetPlayerRID() then ---目前个人信息是二d场景(所有只走3d数据层逻辑)  看其他人是3d
    --    self:BuildHomeExhibit(carCount)
    --else
    --    self:TrophySetup()
    --end
end
