---@param exhibitData ExhibitData
function PersonalHomeDataManager:SetDefaultSiteInfo(exhibitData)
    local dic = exhibitData:GetChildDic()

    for slotId, v in pairs(dic) do
        if slotId>0 then
            ---@type dictpersonalhomeslot_config_cell
            local cfgslotdata = CommonHelper:GetTableDataByID(ConfigNames.dictpersonalhomeslot_config,slotId)
            if cfgslotdata==nil  then
                logError("  槽位表没有该id：  ",slotId)
            else
                if cfgslotdata.default_id>0 then
                    local childExhibit = self.curInfo:GetExhibitByID(cfgslotdata.default_id)
                    if childExhibit then
                        childExhibit:SetParentInfo(exhibitData:GetServerID(),slotId)
                        exhibitData:SetChild(slotId,childExhibit:GetServerID())
                        self:SetDefaultSiteInfo(childExhibit)
                    end
                --elseif cfgslotdata.type == ExhibitType.Trophy then
                --    local childExhibit =self.curInfo:GetUnPutTrophyExhibit()
                --    if childExhibit then
                --        childExhibit:SetParentInfo(exhibitData:GetServerID(),slotId)
                --        exhibitData:SetChild(slotId,childExhibit:GetServerID())
                --        self:SetDefaultSiteInfo(childExhibit)
                --    end
                end
            end
        end
    end
end

function PersonalHomeDataManager:SetExhibitDataSiteInfo(jsonMapNodeDic)
    ---@type table<PersonalHomeMapNode>
    local mapNodeDic = Dll_JSON.decode(jsonMapNodeDic)
    if self.curInfo.rid ~= PlayerDataManager:Get():GetPlayerRID() then
        ----其他玩家房间  由于没有这个玩家的展品信息，根据操作信息生成展品信息
        for i = 1,#mapNodeDic do
            ---@type PersonalHomeMapNode
            local personalHomeMapNode= mapNodeDic[i]
            local exhibitData = ExhibitData(personalHomeMapNode.ServerID,personalHomeMapNode.ID)
            self.curInfo:AddExhibit(exhibitData)
            if i==1 then
                self.curInfo:SetExhibitRootID(personalHomeMapNode.ServerID)
            end
        end
    end

    for i = 1,#mapNodeDic do
        ---@type PersonalHomeMapNode
        local personalHomeMapNode= mapNodeDic[i]
        local exhibitData = self:GetExhibitByServerID(personalHomeMapNode.ServerID)
        for j=1,#personalHomeMapNode.ChildDic do
            ---@type SlotInfo
            local slotInfo=   personalHomeMapNode.ChildDic[j]
            if slotInfo.ChildServerID>0 then
                local childExhibitData = self:GetExhibitByServerID(slotInfo.ChildServerID)
                if childExhibitData == nil  then
                    logError("设置座位信息错误请检查  父节点ID：",personalHomeMapNode.ServerID,"槽位：",slotInfo.SlotID,"子节点ID：",slotInfo.ChildServerID)
                    break
                else
                    childExhibitData:SetParentInfo(personalHomeMapNode.ServerID,slotInfo.SlotID)
                    exhibitData:SetChild(slotInfo.SlotID,slotInfo.ChildServerID)
                end
            end
        end
    end
end


function PersonalHomeDataManager:InitCarByData(cars)
    for i = 1, #cars do
        local param=CarBuilderTextureParam()
        param.CarReviewData=CarReviewData()
        param.CarReviewData:SetDataByMsg(cars[i])
        param.isBuildTexture=false
        param.idx=cars[i].planseq
        self.curInfo:AddCarBuilderParam(param)
    end
end

function PersonalHomeDataManager:BuilderOtherPlayerCars(endFun,changeFun)


    if  self.curInfo.buildParamDic then
        CarBuilderTextureManager:Get():BuildMore(self.curInfo.buildParamDic,function(carList)
            if endFun ~= nil then
                endFun()
            end
        end,function(textureBuilder)
            changeFun()
            if  textureBuilder.CarObj~=nil  then

                if textureBuilder.BuilderData.idx == PersonalHomeDataManager:Get().curInfo.carIndex  then
                    PersonalHomeDataManager:Get():InitCarReplica(textureBuilder.CarObj)
                end
                local root = HomeSceneHelper:GetCarRoot_PersonalHome(textureBuilder.BuilderData.idx)
                UIUtil.SetParentGameObject(root, textureBuilder.CarObj)
            end
        end)
    end

    --- CarBuilderTextureManager:Get():Clear()  ---清理
end

---@param exhibitData
function PersonalHomeDataManager:AddExhibit(exhibitData,isBuild)
    self.selfInfo:AddExhibit(exhibitData)
    if isBuild then
        if self.selfInfo == self.curInfo then
            ExhibitBuilderManager:Get():BuilderOneExhibit(exhibitData)
        end
    end
end


function PersonalHomeDataManager:SetCurBagExhibitDataList(list)
    self.selfInfo.curBagExhibitDataList=list
end

function PersonalHomeDataManager:GetCurBagExhibitDataList()
    return self.selfInfo.curBagExhibitDataList
end


function PersonalHomeDataManager:Exit()
    if self.CurCarReplica then
        GameObject.DestroyImmediate(self.CurCarReplica)
        self.CurCarReplica=nil
    end
    CarBuilderTextureManager:Get():Clear()
    if self.curInfo ~=nil then
        ---@type   table<number, ExhibitData> @展品数据组
        local exhibitDataList= self.curInfo:GetExhibitDic()
        for i, exhibitData in pairs(exhibitDataList) do
            ExhibitBuilderManager:Get():Recycle(exhibitData:GetExhibitBuilderId())
            exhibitData:SetExhibitBuilderId(-1)
        end
    end
    ExhibitBoxMgr:Get():Recycle()
    if self.curInfo then
        self.curInfo.carBuilderDic={}
    end
    self.otherInfo = PersonalHomeData()
    --self.selfInfo = PersonalHomeData()
    self.curInfo = nil
    self.SceneRoot = nil
    self.CurCarReplica = nil
end

function PersonalHomeDataManager:Destroy()
    self:Exit()

    self.curInfo=nil

    ExhibitCacheMgr:Get():ReleaseAllExhibit()

    ExhibitBuilderManager:Get():DestroyCache()

    ExhibitBoxMgr:Get():Destroy()
end
function PersonalHomeDataManager:ClearData()
    self:OnCloseClear()
    self.selfInfo = PersonalHomeData()
    self.otherInfo = PersonalHomeData()
    self.curInfo = nil
    self.SceneRoot = nil
    self.CurCarReplica = nil
end
